// Payload's adapters chosen by the environment: the D1 database, the R2 storage and Resend mail when the Cloudflare bindings are handed to the app
// (OpenNext's worker sets globalThis.__qpuBindings from its env), the site's own MongoDB, Vercel Blob and nodemailer otherwise; the RAID's docket is
// the semantics over whichever database answers. Generated by configure { kind: 'adapters' }; imported by src/payload.config.ts.
import { mongooseAdapter } from '@payloadcms/db-mongodb'
import { sqliteD1Adapter } from '@payloadcms/db-d1-sqlite'
import { postgresAdapter } from '@payloadcms/db-postgres'
import { gcsStorage } from '@payloadcms/storage-gcs'
import { nodemailerAdapter } from '@payloadcms/email-nodemailer'
import { resendAdapter } from '@payloadcms/email-resend'
import { r2Storage } from '@payloadcms/storage-r2'
import { vercelBlobStorage } from '@payloadcms/storage-vercel-blob'
import type { Plugin } from 'payload'

type Bindings = { D1?: unknown; R2?: unknown; KV?: unknown; DOCKET?: unknown; AI?: unknown }
export const qpuBindings = (): Bindings => ((globalThis as { __qpuBindings?: Bindings }).__qpuBindings ?? {})
export const qpuGoogle = (): boolean => !qpuBindings().D1 && (process.env.QPU_ADAPTERS === 'google' || Boolean(process.env.GCS_BUCKET) || Boolean(process.env.GOOGLE_CLOUD_PROJECT))
export const qpuProfile = (): 'cloudflare' | 'google' | 'vercel' | 'local' => (qpuBindings().D1 || process.env.QPU_ADAPTERS === 'cloudflare' ? 'cloudflare' : qpuGoogle() ? 'google' : process.env.BLOB_READ_WRITE_TOKEN ? 'vercel' : 'local')
export const qpuDb = () => { const b = qpuBindings(); return b.D1 ? sqliteD1Adapter({ binding: b.D1 as never }) : qpuGoogle() ? postgresAdapter({ pool: { connectionString: process.env.DATABASE_URI || '' } }) : mongooseAdapter({ url: process.env.DATABASE_URI || '' }) }
export const qpuEmail = () => { const from = { defaultFromAddress: process.env.EMAIL_FROM_ADDRESS || 'no-reply@localhost.test', defaultFromName: process.env.EMAIL_FROM_NAME || 'QPU' }; if (process.env.RESEND_API_KEY) return resendAdapter({ apiKey: process.env.RESEND_API_KEY, ...from }); const transportOptions: Record<string, unknown> | undefined = process.env.GMAIL_USER && process.env.GMAIL_APP_PASSWORD ? { service: 'gmail', auth: { user: process.env.GMAIL_USER, pass: process.env.GMAIL_APP_PASSWORD } } : process.env.SENDGRID_API_KEY ? { host: 'smtp.sendgrid.net', port: 587, auth: { user: 'apikey', pass: process.env.SENDGRID_API_KEY } } : undefined; return nodemailerAdapter({ ...from, ...(transportOptions ? { transportOptions: transportOptions as never } : {}) }) } // Resend over HTTP when its key is named (it runs in a Worker); Gmail or SendGrid over SMTP through nodemailer when theirs are; logged otherwise
export const qpuStoragePlugins = (): Plugin[] => { const b = qpuBindings(); return b.R2 ? [r2Storage({ bucket: b.R2 as never, collections: { media: true } })] : process.env.GCS_BUCKET ? [gcsStorage({ bucket: process.env.GCS_BUCKET, options: { projectId: process.env.GCS_PROJECT_ID || process.env.GOOGLE_CLOUD_PROJECT }, collections: { media: true } })] : [vercelBlobStorage({ cacheControlMaxAge: 60 * 60 * 24 * 365, collections: { media: { generateFileURL: ({ filename }) => `https://${process.env.BLOB_STORE_ID}/${filename}` } }, enabled: Boolean(process.env.BLOB_STORAGE_ENABLED) || false, token: process.env.BLOB_READ_WRITE_TOKEN || '' })] }
